from fractions import Fraction as F
import json
rows=[('A',15,(1,0,0,1)),('A',9,(0,1,1,1)),('B',6,(1,0,0,0)),('B',5,(0,1,0,0)),('C',9,(1,1,1,1)),('C',5,(0,1,1,0)),('D',14,(0,0,0,0)),('D',9,(1,1,1,0))]
tests='TUVW'
cost=dict(zip(tests,map(F,['0.8','1.2','0.7','1.4'])))
loss=[[0,24,11,6],[19,0,19,8],[9,10,0,16],[21,24,20,0]]
def mass(s): return sum(rows[i][1] for i in s)
def stop(s):
    return min((sum(F(rows[i][1]*loss[a][ord(rows[i][0])-65],mass(s)) for i in s),chr(a+65)) for a in range(4))
def split(s,t,b): return tuple(i for i in s if rows[i][2][tests.index(t)]==b)
def value(s,available,n):
    candidates=[stop(s)]
    if n:
        for t in available:
            v=cost[t]
            for b in (0,1):
                sub=split(s,t,b)
                if sub: v+=F(mass(sub),mass(s))*value(sub,available.replace(t,''),n-1)[0]
            candidates.append((v,t))
    return min(candidates)
s=tuple(range(8))
first_losses={'STOP':float(stop(s)[0])}
for t in tests:
    first_losses[t]=float(cost[t]+sum(F(mass(sub),mass(s))*value(sub,tests.replace(t,''),1)[0] for b in (0,1) if (sub:=split(s,t,b))))
v,first=value(s,tests,2)
next_actions={str(b):value(split(s,first,b),tests.replace(first,''),1)[1] if split(s,first,b) else 'IMPOSSIBLE' for b in (0,1)} if first in tests else {}
result={'first':first,'first_losses':first_losses,'next':next_actions}
payload=json.dumps(result)
# Independently enumerate complete two-stage contingent policies, using integer weighted losses.
def weighted_stop(s): return min(sum(rows[i][1]*loss[a][ord(rows[i][0])-65] for i in s) for a in range(4))
checks={'STOP':F(weighted_stop(s),mass(s))}
for t in tests:
    total=cost[t]*mass(s)
    for b in (0,1):
        sub=split(s,t,b)
        if not sub: continue
        options=[F(weighted_stop(sub))]
        for u in tests.replace(t,''):
            options.append(cost[u]*mass(sub)+sum(weighted_stop(child) for c in (0,1) if (child:=split(sub,u,c))))
        total+=min(options)
    checks[t]=total/mass(s)
decoded=json.loads(payload)
assert set(decoded)=={'first','first_losses','next'}
assert all(abs(decoded['first_losses'][k]-float(v))<1e-10 for k,v in checks.items())
assert decoded['first']==min(checks,key=checks.get)
for b,action in decoded['next'].items():
    sub=split(s,decoded['first'],int(b))
    assert action==value(sub,tests.replace(decoded['first'],''),1)[1]
print(payload)
print('Verified all first-action values by independent weighted policy enumeration; branch actions checked.')

