from fractions import Fraction as F
import json
rows=[('A',15,(1,0,0,1)),('A',9,(0,1,1,1)),('B',6,(1,0,0,0)),('B',5,(0,1,0,0)),('C',9,(1,1,1,1)),('C',5,(0,1,1,0)),('D',14,(0,0,0,0)),('D',9,(1,1,1,0))]
loss=[[0,24,11,6],[19,0,19,8],[9,10,0,16],[21,24,20,0]]
tests='TUVW'
cost={'T':F('0.8'),'U':F('1.2'),'W':F('7.4')}
s=[r for r in rows if r[2][2]==0] # repeated display is the same event, not new evidence
mass=sum(r[1] for r in s)
def repair_values(sub):
    m=sum(r[1] for r in sub)
    return {a:sum(F(r[1]*loss[j][ord(r[0])-65],m) for r in sub) for j,a in enumerate('ABCD')}
def best(sub):
    vals=repair_values(sub)
    return min(vals,key=vals.get),min(vals.values())
posterior={a:float(F(sum(r[1] for r in s if r[0]==a),mass)) for a in 'ABCD'}
remaining=repair_values(s)
branches={}
for t in cost:
    val=cost[t]
    branches[t]={}
    for b in (0,1):
        sub=[r for r in s if r[2][tests.index(t)]==b]
        if sub:
            a,v=best(sub)
            val+=F(sum(r[1] for r in sub),mass)*v
            branches[t][str(b)]=a
        else: branches[t][str(b)]='IMPOSSIBLE'
    remaining[t]=val
action=min(remaining,key=remaining.get)
result={'posterior':posterior,'remaining_losses':{k:float(v) for k,v in remaining.items()},'action':action,'repair_after':branches.get(action,{})}
payload=json.dumps(result)
decoded=json.loads(payload)
# Independent mode-count and unnormalized-loss checks.
assert mass==40
assert decoded['posterior']=={'A':0.375,'B':0.275,'C':0.0,'D':0.35}
expected={'A':F(216,40),'B':F(397,40),'C':F(469,40),'D':F(579,40),'T':F('0.8')+F(184,40),'U':F('1.2')+F(198,40),'W':F('7.4')+F(112,40)}
assert set(decoded['remaining_losses'])==set(expected)
for k,v in expected.items(): assert abs(decoded['remaining_losses'][k]-float(v))<1e-10,(k,decoded['remaining_losses'][k],v)
assert decoded['action']=='T'
assert decoded['repair_after']=={'0':'D','1':'A'}
# Exercise stale-W-price rule to verify this update changes the preferred action.
stale=dict(expected); stale['W']=F('1.4')+F(112,40)
assert min(stale,key=stale.get)=='W' and min(expected,key=expected.get)=='T'
print(payload)
print('Validated serialized fields against independent weighted losses; stale-price policy differs.')

